{
  "case_id": "C05",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 90,
  "beats": [
    {
      "beat": "The question",
      "narration": "Can a phone app treat long-term insomnia? Researchers tested a six-week app that delivers cognitive behavioural therapy for insomnia, and compared it against a simpler app that just gave sleep-hygiene advice.",
      "on_screen": "Title card: 'Can an app fix chronic insomnia?' Two phones side by side, labelled 'CBT app' and 'Sleep-hygiene app'.",
      "claim_refs": ["study_id:SYN-C05", "abstract:intervention_and_control"]
    },
    {
      "beat": "How it was tested",
      "narration": "640 adults with chronic insomnia were randomly split between the two apps. Crucially, the team registered two equally important main outcomes in advance: how severe their insomnia was, and how well they functioned during the day. The trial was designed to answer both.",
      "on_screen": "640 figures splitting 1:1 into two groups. Two flags marked 'Co-primary endpoint 1: insomnia severity' and 'Co-primary endpoint 2: daytime functioning'.",
      "claim_refs": ["design", "methods:co-primary_pre-registered", "abstract:n=640_randomised_1:1"]
    },
    {
      "beat": "Result one: better sleep scores",
      "narration": "On insomnia severity at week eight, the CBT app won. Scores fell 6.8 points, against 3.1 in the control group. That's a 3.7-point advantage, and the statistics say it's very unlikely to be chance.",
      "on_screen": "Bar chart: -6.8 vs -3.1. Caption: 'Difference 3.7 points (95% CI 2.9 to 4.5), p<0.001'.",
      "claim_refs": ["results_table[0]"]
    },
    {
      "beat": "Result two: no daytime benefit",
      "narration": "But the second main outcome came up empty. Daytime functioning improved by 1.2 points with CBT and 1.0 in the control group; a difference of 0.2 points, small enough to be noise. So better sleep scores did not translate into a measurably better day.",
      "on_screen": "Bar chart: -1.2 vs -1.0, nearly identical. Caption: 'Difference 0.2 points (95% CI -0.7 to 1.1), p=0.66'. Stamp: 'No difference'.",
      "claim_refs": ["results_table[1]", "limitations[0]"]
    },
    {
      "beat": "The caveats",
      "narration": "Three more things to hold onto. The sleep advantage shrank to 1.9 points by six months. Every outcome was self-reported, with no sleep-lab or wearable measurement. And more people dropped out of the CBT group, 14 percent versus 9.",
      "on_screen": "Three icons with text: line falling from 3.7 to 1.9 at 6 months; a questionnaire with a crossed-out sleep monitor; 14% vs 9% dropout.",
      "claim_refs": ["results_table[2]", "results_table[3]", "limitations[1]", "limitations[2]", "limitations[3]"]
    },
    {
      "beat": "Bottom line",
      "narration": "So: a genuine, short-term improvement in insomnia symptoms, but the trial's own second yardstick showed no gain in daily life, and the benefit faded. Promising, not proven.",
      "on_screen": "Split card: green tick 'Insomnia severity: improved at week 8' / grey cross 'Daytime functioning: no change'. Footer: 'Effect faded by 6 months'.",
      "claim_refs": ["author_conclusion"]
    }
  ]
}
